"use strict";var TYPE_ICON=1,TYPE_CURSOR=2,SIZE_HEADER=6,SIZE_IMAGE_ENTRY=16;function isICO(e){return 0===e.readUInt16LE(0)&&e.readUInt16LE(2)===TYPE_ICON}function getSizeFromOffset(e,t){var r=e.readUInt8(t);return 0===r?256:r}function getImageSize(e,t){var r=SIZE_HEADER+t*SIZE_IMAGE_ENTRY;return{width:getSizeFromOffset(e,r),height:getSizeFromOffset(e,r+1)}}function calculate(e){var t,r=e.readUInt16LE(4),i=getImageSize(e,0);if(1===r)return i;for(i.images=[{width:i.width,height:i.height}],t=1;t<r;t+=1)i.images.push(getImageSize(e,t));return i}module.exports={detect:isICO,calculate:calculate};